"use client";

import { useState } from "react";
import { cn } from "@/lib/utils";

/** The 48 WC2026 FIFA codes that have a bundled SVG in public/flags.
 *
 * Kept as an explicit set so `TeamFlag` can tell "no asset exists for this
 * team" (render the code badge) apart from "the asset failed to load" — the
 * second is a bug worth surfacing, the first is normal for historical sides
 * like West Germany that legitimately have no 2026 flag.
 *
 * Generated by scripts/build-flags.mjs; kept in sync by
 * team-flag.test-ish assertions in the backend flag-coverage test. */
export const FLAGGED_FIFA_CODES = new Set([
  "alg", "arg", "aus", "aut", "bel", "bih", "bra", "cpv", "can", "col",
  "cod", "cro", "cuw", "cze", "civ", "ecu", "egy", "eng", "fra", "ger",
  "gha", "hai", "irn", "irq", "jpn", "jor", "mex", "mar", "ned", "nzl",
  "nor", "pan", "par", "por", "qat", "ksa", "sco", "sen", "rsa", "kor",
  "esp", "swe", "sui", "tun", "tur", "usa", "uru", "uzb",
]);

/** Canonical WC2026 team name -> FIFA code.
 *
 * Needed because several call sites only carry a team *name* (saved
 * predictions, dashboards, prediction results). Keyed on the canonical names
 * used by the backend, including the accented and non-obvious ones
 * ("Côte d'Ivoire", "Türkiye", "IR Iran", "Congo DR", "USA"). */
const NAME_TO_CODE: Record<string, string> = {
  Algeria: "alg", Argentina: "arg", Australia: "aus", Austria: "aut",
  Belgium: "bel", "Bosnia and Herzegovina": "bih", Brazil: "bra",
  "Cabo Verde": "cpv", Canada: "can", Colombia: "col", "Congo DR": "cod",
  Croatia: "cro", "Curaçao": "cuw", Czechia: "cze", "Côte d'Ivoire": "civ",
  Ecuador: "ecu", Egypt: "egy", England: "eng", France: "fra", Germany: "ger",
  Ghana: "gha", Haiti: "hai", "IR Iran": "irn", Iraq: "irq", Japan: "jpn",
  Jordan: "jor", Mexico: "mex", Morocco: "mar", Netherlands: "ned",
  "New Zealand": "nzl", Norway: "nor", Panama: "pan", Paraguay: "par",
  Portugal: "por", Qatar: "qat", "Saudi Arabia": "ksa", Scotland: "sco",
  Senegal: "sen", "South Africa": "rsa", "South Korea": "kor", Spain: "esp",
  Sweden: "swe", Switzerland: "sui", Tunisia: "tun", "Türkiye": "tur",
  USA: "usa", Uruguay: "uru", Uzbekistan: "uzb",
};

/** Resolves a team to its bundled-flag code, preferring an explicit FIFA code
 * and falling back to the canonical name. Returns "" when the team has no
 * 2026 flag (historical sides, unresolved bracket slots). */
export function flagCodeFor(name?: string | null, fifaCode?: string | null): string {
  const explicit = fifaCode?.trim().toLowerCase() ?? "";
  if (explicit.length === 3 && FLAGGED_FIFA_CODES.has(explicit)) return explicit;
  const byName = name ? NAME_TO_CODE[name.trim()] : undefined;
  return byName ?? "";
}

const sizeClass = {
  xs: "h-3 w-4",
  sm: "h-4 w-[1.4rem]",
  md: "h-5 w-[1.7rem]",
  lg: "h-7 w-[2.4rem]",
} as const;

interface TeamFlagProps {
  /** Team name, used for the accessible label. */
  name: string;
  /** 3-letter FIFA code — the canonical team identity used across the app. */
  fifaCode?: string | null;
  size?: keyof typeof sizeClass;
  className?: string;
}

/**
 * A national flag, rendered from a locally bundled SVG.
 *
 * Deliberately not emoji: Windows ships no country-flag glyphs, so
 * `🇧🇷` renders as the letters "BR" there — the previous implementation showed
 * no flags at all on Windows. Deliberately not a CDN either: these must work
 * offline and without a third-party request.
 *
 * Every flag falls back to a FIFA-code badge rather than a broken-image icon,
 * so a missing asset degrades to something legible instead of a broken glyph.
 * The single source of flag rendering in the app — do not inline <img
 * src="/flags/..."> elsewhere.
 */
export function TeamFlag({ name, fifaCode, size = "sm", className }: TeamFlagProps) {
  const code = flagCodeFor(name, fifaCode);
  const hasAsset = code.length === 3 && FLAGGED_FIFA_CODES.has(code);
  const [failed, setFailed] = useState(false);

  if (!hasAsset || failed) {
    return (
      <span
        role="img"
        aria-label={`${name} (no flag available)`}
        title={name}
        className={cn(
          "inline-flex shrink-0 items-center justify-center rounded-[2px] border border-border bg-surface-2",
          "font-mono text-[8px] uppercase leading-none tracking-tight text-fg-muted",
          sizeClass[size],
          className
        )}
      >
        {(fifaCode?.trim() || code).toUpperCase().slice(0, 3) || "—"}
      </span>
    );
  }

  return (
    // Plain <img>, not next/image: these are tiny static SVGs already in
    // /public, so the optimizer would add work without reducing bytes.
    // eslint-disable-next-line @next/next/no-img-element
    <img
      src={`/flags/${code}.svg`}
      alt={`${name} flag`}
      loading="lazy"
      decoding="async"
      onError={() => setFailed(true)}
      className={cn(
        "shrink-0 rounded-[2px] object-contain ring-1 ring-inset ring-white/10",
        sizeClass[size],
        className
      )}
    />
  );
}
